}

const BOARD_STALE_TIME_MS = 30_000;

function resolveFallbackBoardColumns(): ISubstatusKanbanBoardColumnView[] {
    return LIQUIDACAO_KANBAN_PHASES.map((phase) => ({
        id: phase.id,
        name: phase.label,
        cards: [],
    }));
}

function mapBoardColumns(
    columns: TSubstatusKanbanBoardResponse['columns'] | undefined,
): ISubstatusKanbanBoardColumnView[] {
    if (!columns?.length) {
        return resolveFallbackBoardColumns();
    }

    return columns.map((column) => ({
        id: column.id,
        name: column.name,
        cards: column.cards,
    }));
}

export function resolveSubstatusKanbanBoardTotalLabel(total: number): string {
    const noun = total === 1 ? 'operação' : 'operações';
    return `${total} ${noun} no quadro · clique no card para abrir a liquidação · atualizações em tempo real`;
}

function boardContainsDueId(
    board: TSubstatusKanbanBoardResponse | undefined,
    dueId: string,
): boolean {
    if (!board?.columns) {
        return false;
    }

    return board.columns.some((column) =>
        column.cards.some((card) => String(card.id) === String(dueId)),
    );
}

